// Generates supabase/seed.sql from content/seed/content.json. Run: npx tsx scripts/seed-sql.ts
import { readFileSync, writeFileSync } from 'node:fs';
import { Snapshot } from '../src/content/schema';

const snap = Snapshot.parse(JSON.parse(readFileSync('content/seed/content.json', 'utf8')));
const q = (s: string) => `'${s.replace(/'/g, "''")}'`;
const j = (v: unknown) => `${q(JSON.stringify(v))}::jsonb`;
const arr = (a: string[]) => `array[${a.map(q).join(', ')}]::text[]`;

const lines = [
  '-- Generated by scripts/seed-sql.ts from content/seed/content.json. Placeholder content only.',
  `insert into public.site_settings (id, studio_statement, intro_enabled) values (1, ${q(snap.settings.studioStatement)}, ${snap.settings.introEnabled}) on conflict (id) do nothing;`,
  ...snap.members.map(
    (m) =>
      `insert into public.members (slug, name, role_title, bio, links, avatar) values (${q(m.slug)}, ${q(m.name)}, ${q(m.role)}, ${q(m.bio)}, ${j(m.links)}, ${j(m.avatar)}) on conflict (slug) do nothing;`,
  ),
  ...snap.projects.map(
    (p) =>
      `insert into public.projects (slug, name, summary, status, platforms, tech, links, repo, featured, screenshots) values (${q(p.slug)}, ${q(p.name)}, ${q(p.summary)}, ${q(p.status)}, ${arr(p.platforms)}, ${arr(p.tech)}, ${j(p.links)}, ${p.repo ? q(p.repo) : 'null'}, ${p.featured}, ${j(p.screenshots)}) on conflict (slug) do nothing;`,
  ),
  ...snap.memberships.map(
    (m) =>
      `insert into public.project_members (project_id, member_id) select p.id, m.id from public.projects p, public.members m where p.slug = ${q(m.projectSlug)} and m.slug = ${q(m.memberSlug)} on conflict do nothing;`,
  ),
];
writeFileSync('supabase/seed.sql', lines.join('\n') + '\n');
console.log(`wrote supabase/seed.sql (${lines.length - 1} statements)`);
